              "cálculos conferidos": True, "permissões OK": True}

    metrics_dir = self.project_root / "harness" / "metrics"
    artifacts = []
    if metrics_dir.is_dir():
        artifacts = sorted(p for p in metrics_dir.glob("*.jsonl") if p.is_file())

