                        continue
                    status = str(json.loads(line).get("status", "") or "").lower()
                    if status and status not in (
                            "success", "passed", "ok", "running", "in_progress"):
                        checks["cálculos conferidos"] = False
                        break
        except (OSError, ValueError):
            checks["cálculos conferidos"] = False
        break

